import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"内部机制：熵与加密核心","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/drbg-crypto.md","filePath":"zh/internals/drbg-crypto.md"}'),l={name:"zh/internals/drbg-crypto.md"};function i(d,e,n,c,s,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="内部机制-熵与加密核心" tabindex="-1">内部机制：熵与加密核心 <a class="header-anchor" href="#内部机制-熵与加密核心" aria-label="Permalink to &quot;内部机制：熵与加密核心&quot;">​</a></h1><p><code>kernel/crypto/crypto_core.c</code> - RNG 以及协议所构建的哈希/MAC/AEAD 原语。</p><h2 id="种子" tabindex="-1">种子 <a class="header-anchor" href="#种子" aria-label="Permalink to &quot;种子&quot;">​</a></h2><p>基于 HMAC-SHA-256 的 HMAC_DRBG (NIST SP 800-90A)，种子来源：</p><ul><li><strong>RDRAND</strong>（CPU 熵 - 通过 CPUID 验证），</li><li><strong>RDTSC</strong>，每次生成调用后重新混合，因此部分状态 攻击无法持久。</li></ul><p>（rdrand 包装器的 <code>setc</code> 标志是更严格的 CI 汇编程序强制修正的正确性 - 可移植性说明参见 <a href="./../dev/portability.html">../dev/portability.md</a>。）</p><h2 id="原语族" tabindex="-1">原语族 <a class="header-anchor" href="#原语族" aria-label="Permalink to &quot;原语族&quot;">​</a></h2><ul><li>AES、SHA-2 族、HMAC - NIST 向量验证（<code>cryptotest</code>）。</li><li>RSA、NIST 曲线、curve25519 风格、Ed25519 风格 - TLS/SSH 密钥交换（<code>dhtest</code> 计时并验证 group-14 模幂）。</li><li>AEAD (GCM)、X.509 解析 + 链验证（RFC 6125 策略）。</li></ul><h2 id="形成它的审计轨迹" tabindex="-1">形成它的审计轨迹 <a class="header-anchor" href="#形成它的审计轨迹" aria-label="Permalink to &quot;形成它的审计轨迹&quot;">​</a></h2><p>旧的 LCG 已被替换（对观察者可见重复）；TCP RX 校验和链错误（双补码）和 TLS 握手中途主机名错误是两个著名的加密相关修复</p><ul><li>现在都已通过回归测试。</li></ul>',11)])])}const u=a(l,[["render",i]]);export{_ as __pageData,u as default};
